#define WORD "CODEFORCES"
#define WORD_LEN 10

int doit(const char *word) {
    size_t len = strlen(word);
    if (len < WORD_LEN) return 0;

    // Check if word starts with WORD
    if (strncmp(word, WORD, WORD_LEN) == 0) return 1;

    // Check if word ends with WORD
    if (strncmp(word + (len - WORD_LEN), WORD, WORD_LEN) == 0) return 1;

    // Check for interleaving: word[0..i-1] == WORD[0..i-1] and word[len-i..len-1] == WORD[i..WORD_LEN-1]
    for (int i = 1; i < WORD_LEN; i++) {
        int ok = 1;
        // Check prefix
        for (int j = 0; j < i; j++) {
            if (word[j] != WORD[j]) {
                ok = 0;
                break;
            }
        }
        if (!ok) continue;

        // Check suffix
        for (int j = i; j < WORD_LEN; j++) {
            if (word[len - (WORD_LEN - j)] != WORD[j]) {
                ok = 0;
                break;
            }
        }
        if (ok) return 1;
    }

    return 0;
}

int main() {
    char *s = (char *)malloc(100000 * sizeof(char));
    if (!s) return 1;
    if (fgets(s, 100000, stdin) == NULL) {
